mat2 rot(float a) { float s = sin(a), c = cos(a); return mat2(c, -s, s, c); }
float map(vec3 p) {
  p.xz = rot(time * 0.2) * p.xz;
  vec3 q = abs(p);
  float hull = max(q.x - 1.4, max(q.y - 0.4, q.z - 0.8));
  float trench = max(q.x - 1.5, max(abs(p.y) - 0.08, q.z - 0.9));
  float fortress = max(hull, -trench);
  float towers = length(q.xz - vec2(1.1, 0.5)) - 0.2;
  towers = max(towers, q.y - 0.7);
  return min(fortress, towers);
}
shader_body {
  vec2 p = (uv - 0.5) * vec2(aspect.x, 1.0) * 2.0;
  vec3 ro = vec3(0.0, 1.2, -3.5);
  vec3 rd = normalize(vec3(p, 1.5));
  rd.yz = rot(-0.3) * rd.yz;
  float t = 0.0;
  for (int i = 0; i < 48; i++) {
    float d = map(ro + rd * t);
    if (d < 0.003 || t > 9.0) break;
    t += d * 0.8;
  }
  vec3 col = vec3(0.02, 0.04, 0.08);
  if (t < 9.0) {
    vec3 pos = ro + rd * t;
    vec2 e = vec2(0.004, 0.0);
    vec3 n = normalize(vec3(
      map(pos + e.xyy) - map(pos - e.xyy),
      map(pos + e.yxy) - map(pos - e.yxy),
      map(pos + e.yyx) - map(pos - e.yyx)
    ));
    vec3 l = normalize(vec3(1.0, 2.0, -1.0));
    float diff = max(dot(n, l), 0.0);
    float spec = pow(max(dot(reflect(-l, n), -rd), 0.0), 24.0);
    float bayGlow = step(0.04, -pos.y) * step(abs(pos.y), 0.07) * 2.0;
    col = vec3(0.05, 0.08, 0.12) + diff * vec3(0.4, 0.6, 0.8) + spec * vec3(0.8, 0.9, 1.0) + bayGlow * vec3(0.1, 0.8, 1.0);
  }
  ret = col;
}
